using CourseWaitlist.Core;

namespace CourseWaitlist.Cli;

/// <summary>A preloaded learner shown in the console.</summary>
public sealed record SampleLearner(string Id, string Name, string[] Completed);

/// <summary>
/// Interactive console front end over the same <see cref="EnrollmentService"/> the API uses.
/// Learners are shown in a numbered table; when asked for a learner you can type the row number, the ID, or part of the name.
/// IDs are generated by the console (L101, L102, ...), so a number typed by the user is never mistaken for a new learner.
/// Input and output are injected so the console can be tested with scripted input.
/// </summary>
public sealed class CliApp
{
    public const string OfferingCode = "NET301";
    public const string PrerequisiteCode = "CSH101";

    /// <summary>Display names for course codes (the service itself only works with codes).</summary>
    public static IReadOnlyDictionary<string, string> CourseNames { get; } = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["NET301"] = "ASP.NET Core Web API Development",
        ["CSH101"] = "C# Fundamentals",
        ["JS101"] = "JavaScript Basics",
        ["SQL101"] = "SQL Fundamentals",
        ["GIT101"] = "Git Essentials",
    };

    /// <summary>Sample learners. Everyone except Rakesh Verma and Sarah Johnson has completed CSH101.</summary>
    public static IReadOnlyList<SampleLearner> SampleLearners { get; } =
    [
        new("L101", "Ramesh Kumar", ["CSH101", "SQL101"]),
        new("L102", "Priya Sharma", ["CSH101"]),
        new("L103", "Arjun Reddy", ["CSH101", "JS101"]),
        new("L104", "Ananya Iyer", ["CSH101", "GIT101"]),
        new("L105", "John Miller", ["CSH101"]),
        new("L106", "Emily Davis", ["CSH101", "SQL101"]),
        new("L107", "Rakesh Verma", ["JS101"]),
        new("L108", "Sarah Johnson", ["SQL101", "GIT101"]),
    ];

    private const int FirstGeneratedId = 109;
    private const int MaxNameLength = 40;

    private readonly TextReader _in;
    private readonly TextWriter _out;
    private readonly OfferingConfig _config;
    private InMemoryLearnerRecords _records = new();
    private Dictionary<string, string> _names = new(StringComparer.Ordinal);
    private EnrollmentService _service;
    private int _nextId = FirstGeneratedId;

    public CliApp(TextReader input, TextWriter output, OfferingConfig config)
    {
        _in = input;
        _out = output;
        _config = config;
        _service = ResetState();
    }

    // ---------------------------------------------------------------- interactive mode

    /// <summary>Runs the menu loop until the user exits or input ends. Returns the process exit code.</summary>
    public int RunInteractive()
    {
        _out.WriteLine("=== Course Waitlist console ===");
        _out.WriteLine("Data lives in memory only and is cleared when the program exits.");
        _out.WriteLine();
        ShowCourseAndLearners();
        _out.WriteLine();
        _out.WriteLine("Tip: when asked for a learner, type the # from the table (for example 1), the ID (L101) or part of the name (Ramesh).");

        while (true)
        {
            _out.WriteLine();
            _out.WriteLine("1) Enroll   2) Drop   3) Show course & learners   4) Add learner   5) Update completed courses   6) Guided demo   7) Reset   0) Exit");
            var choice = Prompt("Choose");
            if (choice is null) return 0;   // input closed (for example piped input ended)

            switch (choice)
            {
                case "1": Enroll(); break;
                case "2": Drop(); break;
                case "3": ShowCourseAndLearners(); break;
                case "4": AddLearner(); break;
                case "5": UpdateCourses(); break;
                case "6": RunDemo(); break;
                case "7":
                    _service = ResetState();
                    _out.WriteLine("Reset: the course is empty and the sample learners are reloaded.");
                    ShowCourseAndLearners();
                    break;
                case "0" or "q" or "exit":
                    _out.WriteLine("Bye.");
                    return 0;
                default:
                    _out.WriteLine($"Unknown option '{choice}'. Type a number from the menu.");
                    break;
            }
        }
    }

    private void Enroll()
    {
        ShowLearnerTable();
        var id = AskForLearner("Learner to enroll (#, ID or name)");
        if (id is null) return;

        var r = _service.Enroll(id);
        _out.WriteLine($"[{r.Status}] {Friendly(r.Message)}");
        if (r.Status == EnrollStatus.UnknownLearner) _out.WriteLine("  Use a # or ID from the table, or add the learner with option 4.");
        ShowSummary();
    }

    private void Drop()
    {
        ShowLearnerTable();
        var id = AskForLearner("Learner to drop (#, ID or name)");
        if (id is null) return;

        var r = _service.Drop(id);
        _out.WriteLine($"[{r.Status}] {Friendly(r.Message)}");
        if (r.PromotedLearnerIds.Count > 0) _out.WriteLine($"  promoted from the waitlist: {Names(r.PromotedLearnerIds)}");
        if (r.SkippedLearnerIds.Count > 0) _out.WriteLine($"  skipped (prerequisite not met, kept their place): {Names(r.SkippedLearnerIds)}");
        ShowSummary();
    }

    private void AddLearner()
    {
        var name = Prompt("Full name of the new learner");
        if (name is null) return;
        if (name.Length is 0 or > MaxNameLength)
        {
            _out.WriteLine($"[InvalidRequest] Name must be 1-{MaxNameLength} characters.");
            return;
        }

        var courses = AskForCourses();
        if (courses is null) return;

        var id = $"L{_nextId++}";
        _records.Upsert(id, courses);
        _names[id] = name;
        _out.WriteLine($"[Added] {Display(id)} - completed: {CoursesText(courses)} - prerequisite {PrerequisiteCode} met: {(IsEligible(id) ? "Yes" : "No")}");
        ShowLearnerTable();
    }

    private void UpdateCourses()
    {
        ShowLearnerTable();
        var id = AskForLearner("Learner to update (#, ID or name)");
        if (id is null) return;
        if (!_names.ContainsKey(id))
        {
            _out.WriteLine($"[UnknownLearner] No learner '{id}'. Use a # or ID from the table.");
            return;
        }

        var courses = AskForCourses();
        if (courses is null) return;

        _records.Upsert(id, courses);
        _out.WriteLine($"[Updated] {Display(id)} - completed: {CoursesText(courses)} - prerequisite {PrerequisiteCode} met: {(IsEligible(id) ? "Yes" : "No")}");

        // Records changed, so a skipped waitlisted learner may now qualify for an open seat.
        var promoted = _service.FillOpenSeats();
        if (promoted.Count > 0) _out.WriteLine($"  promoted after the update: {Names(promoted)}");
        ShowSummary();
    }

    // ---------------------------------------------------------------- display

    private void ShowCourseAndLearners()
    {
        var s = _service.Snapshot();
        _out.WriteLine($"Course       : {CourseLabel(_config.OfferingId)}");
        _out.WriteLine($"Prerequisite : {(_config.RequiredPrerequisite is null ? "none" : CourseLabel(_config.RequiredPrerequisite))}");
        _out.WriteLine($"Seats        : {s.Capacity} total | {s.Enrolled.Count} taken | {s.SeatsAvailable} free      Waitlist: {s.Waitlist.Count} learner(s)");
        ShowLearnerTable();
    }

    private void ShowLearnerTable()
    {
        var s = _service.Snapshot();
        var learners = _records.All();
        var rows = learners.Select((l, i) =>
        {
            var position = s.Waitlist.ToList().IndexOf(l.Id);
            var status = s.Enrolled.Contains(l.Id) ? "Enrolled"
                : position >= 0 ? $"Waitlist #{position + 1}"
                : "Not enrolled";
            return new[]
            {
                (i + 1).ToString(), l.Id, Name(l.Id), CoursesText(l.CompletedCourses),
                IsEligible(l.Id) ? "Yes" : "No", status
            };
        }).ToList();

        var prereqHeader = _config.RequiredPrerequisite is null ? "Prereq met?" : $"Has {_config.RequiredPrerequisite}?";
        WriteTable(["#", "ID", "Name", "Completed courses", prereqHeader, "Status"], rows);

        var codes = learners.SelectMany(l => l.CompletedCourses).Append(_config.RequiredPrerequisite ?? PrerequisiteCode)
            .Distinct(StringComparer.OrdinalIgnoreCase).Order(StringComparer.OrdinalIgnoreCase)
            .Select(c => $"{c.ToUpperInvariant()} = {CourseNames.GetValueOrDefault(c, "?")}");
        _out.WriteLine($"Course codes: {string.Join(", ", codes)}");
    }

    private void ShowSummary()
    {
        var s = _service.Snapshot();
        var waitlist = s.Waitlist.Count == 0 ? "(empty)" : string.Join("  ", s.Waitlist.Select((id, i) => $"{i + 1}. {Name(id)}"));
        _out.WriteLine($"  Now -> seats {s.Enrolled.Count}/{s.Capacity} taken | enrolled: {(s.Enrolled.Count == 0 ? "(none)" : Names(s.Enrolled))} | waitlist: {waitlist}");
    }

    private void WriteTable(string[] headers, IReadOnlyList<string[]> rows)
    {
        var widths = headers.Select((h, i) => Math.Max(h.Length, rows.Count == 0 ? 0 : rows.Max(r => r[i].Length))).ToArray();
        var line = "+" + string.Join("+", widths.Select(w => new string('-', w + 2))) + "+";
        string Row(string[] cells) => "| " + string.Join(" | ", cells.Select((c, i) => c.PadRight(widths[i]))) + " |";

        _out.WriteLine(line);
        _out.WriteLine(Row(headers));
        _out.WriteLine(line);
        foreach (var r in rows) _out.WriteLine(Row(r));
        _out.WriteLine(line);
    }

    // ---------------------------------------------------------------- guided demo

    /// <summary>
    /// Runs the full scenario on its own fresh state (NET301, capacity 2, prerequisite CSH101), printing expected and actual
    /// results for every step. Does not touch the interactive state. Returns 0 when every check matches.
    /// </summary>
    public int RunDemo()
    {
        var records = new InMemoryLearnerRecords();
        foreach (var l in SampleLearners) records.Upsert(l.Id, l.Completed);
        var service = new EnrollmentService(new OfferingConfig(OfferingCode, 2, PrerequisiteCode), records);
        var names = SampleLearners.ToDictionary(l => l.Id, l => l.Name);

        string Enroll(string id)
        {
            var r = service.Enroll(id);
            return r.Status == EnrollStatus.Waitlisted ? $"Waitlisted #{r.WaitlistPosition}" : r.Status.ToString();
        }

        string Drop(string id)
        {
            var r = service.Drop(id);
            return r.Status == DropStatus.Dropped
                ? $"Dropped; promoted [{string.Join(", ", r.PromotedLearnerIds.Select(x => names[x]))}]; skipped [{string.Join(", ", r.SkippedLearnerIds.Select(x => names[x]))}]"
                : r.Status.ToString();
        }

        string State()
        {
            var s = service.Snapshot();
            return $"enrolled [{string.Join(", ", s.Enrolled.Select(x => names[x]))}]; waitlist [{string.Join(", ", s.Waitlist.Select(x => names[x]))}]";
        }

        // (title, action, expected); a null expected marks a setup step that is not checked
        var steps = new List<(string Title, Func<string> Act, string? Expected)>
        {
            ("Ramesh Kumar enrolls (seat free)", () => Enroll("L101"), "Enrolled"),
            ("Priya Sharma enrolls (last seat)", () => Enroll("L102"), "Enrolled"),
            ("Arjun Reddy enrolls (course full)", () => Enroll("L103"), "Waitlisted #1"),
            ("John Miller enrolls (course full)", () => Enroll("L105"), "Waitlisted #2"),
            ("Rakesh Verma enrolls (has not done CSH101)", () => Enroll("L107"), "NotEligible"),
            ("Ramesh Kumar enrolls again (duplicate)", () => Enroll("L101"), "AlreadyEnrolled"),
            ("Arjun Reddy enrolls again (duplicate on the waitlist)", () => Enroll("L103"), "AlreadyWaitlisted"),
            ("blank learner id", () => Enroll("   "), "InvalidRequest"),
            ("Ramesh Kumar drops (earliest waitlisted learner is promoted)", () => Drop("L101"), "Dropped; promoted [Arjun Reddy]; skipped []"),
            ("Ramesh Kumar drops again (repeated drop)", () => Drop("L101"), "NotEnrolled"),
            ("state", State, "enrolled [Priya Sharma, Arjun Reddy]; waitlist [John Miller]"),
            ("Emily Davis enrolls (course full)", () => Enroll("L106"), "Waitlisted #2"),
            ("setup: John Miller's CSH101 record is withdrawn while he waits", () => { records.Upsert("L105", []); return "John is now ineligible"; }, null),
            ("Priya Sharma drops (John is first in line but ineligible)", () => Drop("L102"), "Dropped; promoted [Emily Davis]; skipped [John Miller]"),
            ("state (John skipped but kept his place)", State, "enrolled [Arjun Reddy, Emily Davis]; waitlist [John Miller]"),
            ("setup: John Miller completes CSH101", () => { records.Upsert("L105", [PrerequisiteCode]); return "John is eligible again"; }, null),
            ("Arjun Reddy drops (John gets the seat from his original place)", () => Drop("L103"), "Dropped; promoted [John Miller]; skipped []"),
            ("final state", State, "enrolled [Emily Davis, John Miller]; waitlist []"),
        };

        _out.WriteLine($"Guided demo: {CourseLabel(OfferingCode)}, capacity 2, prerequisite {CourseLabel(PrerequisiteCode)}");
        _out.WriteLine("Learners: Ramesh Kumar, Priya Sharma, Arjun Reddy, John Miller, Emily Davis (completed CSH101), Rakesh Verma (has not)");
        _out.WriteLine();

        int number = 0, checks = 0, matched = 0;
        foreach (var (title, act, expected) in steps)
        {
            var actual = act();
            if (expected is null)
            {
                _out.WriteLine($"     -- {title}");
                continue;
            }

            number++;
            checks++;
            var ok = actual == expected;
            if (ok) matched++;
            _out.WriteLine($"{number,3}. {title}");
            _out.WriteLine($"     -> {actual}   [{(ok ? "OK" : "MISMATCH")}]");
            if (!ok) _out.WriteLine($"     expected: {expected}");
        }

        _out.WriteLine();
        _out.WriteLine($"Demo result: {matched}/{checks} checks matched the expected behaviour.");
        return matched == checks ? 0 : 1;
    }

    // ---------------------------------------------------------------- helpers

    private EnrollmentService ResetState()
    {
        _records = new InMemoryLearnerRecords();
        _names = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var l in SampleLearners)
        {
            _records.Upsert(l.Id, l.Completed);
            _names[l.Id] = l.Name;
        }
        _nextId = FirstGeneratedId;
        return new EnrollmentService(_config, _records);
    }

    /// <summary>
    /// Turns what the user typed into a learner ID: a row number, an ID (case-insensitive) or a unique part of a name.
    /// Anything else is passed through unchanged so the service reports it (InvalidRequest / UnknownLearner).
    /// Returns null when the user typed a row number that does not exist or the input ended.
    /// </summary>
    private string? AskForLearner(string label)
    {
        var input = Prompt(label);
        if (input is null) return null;

        var learners = _records.All();
        if (int.TryParse(input, out var row))
        {
            if (row >= 1 && row <= learners.Count) return learners[row - 1].Id;
            _out.WriteLine($"There is no row #{row}. Pick a number from 1 to {learners.Count}.");
            return null;
        }

        var byId = learners.FirstOrDefault(l => string.Equals(l.Id, input, StringComparison.OrdinalIgnoreCase));
        if (byId is not null) return byId.Id;

        var byName = input.Length == 0 ? [] : learners.Where(l => Name(l.Id).Contains(input, StringComparison.OrdinalIgnoreCase)).ToList();
        if (byName.Count == 1) return byName[0].Id;
        if (byName.Count > 1)
        {
            _out.WriteLine($"'{input}' matches {byName.Count} learners ({Names(byName.Select(l => l.Id))}). Use the # or ID instead.");
            return null;
        }

        return input;
    }

    private string[]? AskForCourses()
    {
        var available = string.Join(", ", CourseNames.Where(kv => kv.Key != OfferingCode).Select(kv => $"{kv.Key} = {kv.Value}"));
        _out.WriteLine($"Course codes: {available}");
        var input = Prompt("Completed course codes (comma separated, blank for none)");
        return input?.Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)
            .Select(c => c.ToUpperInvariant()).Distinct().ToArray();
    }

    private bool IsEligible(string id) =>
        _config.RequiredPrerequisite is null
        || (_records.TryGet(id, out var l) && l.CompletedCourses.Contains(_config.RequiredPrerequisite));

    private string Name(string id) => _names.GetValueOrDefault(id, id);

    private string Display(string id) => _names.TryGetValue(id, out var n) ? $"{n} ({id})" : id;

    private string Names(IEnumerable<string> ids) => string.Join(", ", ids.Select(Name));

    private static string CourseLabel(string code) =>
        CourseNames.TryGetValue(code, out var name) ? $"{code} - {name}" : code;

    private static string CoursesText(IEnumerable<string> codes)
    {
        var list = codes.Select(c => c.ToUpperInvariant()).Order(StringComparer.Ordinal).ToList();
        return list.Count == 0 ? "(none)" : string.Join(", ", list);
    }

    /// <summary>Replaces quoted learner IDs and the prerequisite code in service messages with readable names.</summary>
    private string Friendly(string message)
    {
        foreach (var (id, name) in _names) message = message.Replace($"'{id}'", $"{name} ({id})");
        if (_config.RequiredPrerequisite is { } p) message = message.Replace($"'{p}'", $"'{CourseLabel(p)}'");
        return message;
    }

    private string? Prompt(string label)
    {
        _out.Write($"{label}> ");
        var line = _in.ReadLine();
        if (line is null)
        {
            _out.WriteLine();
            return null;
        }
        return line.Trim();
    }
}
